<script setup>
import {onBeforeUnmount,onMounted,ref} from 'vue'
import {apiGet} from '../services/api.js'
import {formatarNumero as num,formatarPercentual as pct} from '../utils/format.js'
import {today} from '../utils.js'
const data=ref(null),error=ref(''),filter=ref({from:today().slice(0,7)+'-01',to:today().slice(0,4)+'-12-31',company:''});let timer,busy=false
async function load(){if(busy)return;busy=true;try{data.value=await apiGet('/demo/outreach/dashboard?'+new URLSearchParams(filter.value));error.value=''}catch(e){error.value=e.message}finally{busy=false}}
onMounted(()=>{load();timer=setInterval(load,2000)});onBeforeUnmount(()=>clearInterval(timer))
</script>
<template><section class="mb-4" data-testid="management-insights"><p class="eyebrow">SIMULAÇÃO · CRITÉRIO DE SUCESSO</p><h2 class="h3">{{data?.kind==='company'?'Boletim agregado da empresa':'O retorno virou cuidado?'}}</h2><p v-if="error" class="alert alert-danger">{{error}}</p><template v-if="data"><p v-if="data.suppressed" class="alert alert-info">{{data.message}}</p><template v-else><form class="d-flex flex-wrap gap-2 mb-3" @submit.prevent="load"><label>De<input v-model="filter.from" type="date" required class="form-control"></label><label>Até<input v-model="filter.to" type="date" required class="form-control"></label><label v-if="data.kind==='sesi'">Empresa<select v-model="filter.company" class="form-select"><option value="">Todas autorizadas nesta base</option><option v-for="c in data.companies" :key="c">{{c}}</option></select></label><button class="btn btn-outline-success align-self-end">Aplicar</button></form>
<template v-if="data.kind==='company'"><p>{{data.message}}</p><div class="row g-3"><article v-for="(value,key) in data.participation" :key="key" class="col-6 col-md-4"><div class="card card-body"><strong class="h3">{{key==='on_time_percent'?pct(value):num(value)}}</strong><span>{{({due:'Retornos devidos',responded:'Respostas',confirmed_or_rescheduled:'Confirmou ou remarcou',attended:'Comparecimentos',on_time_percent:'Retornos no prazo'})[key]}}</span></div></article></div><p v-for="c in data.campaigns" :key="c.name" class="mt-3">{{c.name}}: {{c.responded}} respostas entre {{c.invited}} convidados.</p></template>
<template v-else><div class="row g-2 mb-3" data-demo="funil"><div v-for="stage in data.funnel" :key="stage.label" class="col-6 col-lg"><article class="card card-body h-100"><strong class="h3">{{num(stage.value)}}</strong><span>{{stage.label}}</span></article></div></div><div class="row g-3 mb-3" data-demo="niveis"><div v-for="level in data.levels" :key="level.title" class="col-md-4"><article class="card card-body h-100"><h3 class="h5">{{level.title}}</h3><strong class="h3">{{pct(level.value)}}</strong><p class="small mb-0">{{level.text}}</p></article></div></div><RouterLink to="/campaign-management" class="btn btn-success mb-3">Campanhas: manter, ajustar ou redesenhar →</RouterLink>
<section class="card card-body mb-3"><h3 class="h5">Operação · estimativa</h3><p>{{num(data.operation.contacts_avoided)}} contatos manuais evitados · {{num(data.operation.hours_saved,2)}} horas de enfermagem poupadas.</p><small>{{data.operation.formula}}</small><h4 class="h6 mt-3">Motivos de “não posso ir”</h4><p v-for="b in data.barriers" :key="b.name">{{b.name}}: {{num(b.count)}}</p><p v-if="!data.barriers.length">Nenhuma barreira informada nesta visita e período.</p></section>
<section class="card card-body mb-3"><p class="eyebrow">EXEMPLO ILUSTRATIVO DE APURAÇÃO</p><h3 class="h5">PPR · {{data.recognition.name}}</h3><p><strong>{{pct(data.recognition.result.rp_percent)}}</strong> contra {{pct(data.recognition.result.baseline_percent)}} · ganho {{num(data.recognition.result.gain_pp,1)}} pontos · degrau {{data.recognition.result.proposed_percent}}% do salário do trimestre.</p><p>Travas aprovadas no exemplo: satisfação 94%, nenhuma queixa de pressão procedente e auditoria de rebaixamento de risco liberada.</p><small>{{data.recognition.source}} Não autoriza pagamento.</small></section></template>
<section class="card card-body mb-3"><h3 class="h5">Bonificação do trabalhador · semestre</h3><p>{{data.eligibility_suppressed?'grupo pequeno demais para exibir':num(data.eligible)+' elegíveis'}}</p><p class="small mb-0">{{data.eligibility_criterion}} A empresa escolhe o benefício; participação opcional e resgate por decisão do trabalhador.</p></section><details class="card card-body"><summary>Como medimos</summary><p class="mt-2 mb-0">Implantação escalonada por estabelecimento. Os locais que ainda não receberam a solução servem de comparação nas mesmas janelas; não comparamos quem vai com quem não vai. Custos são estimativas e os dados desta demonstração são sintéticos. Confirmação não comprova comparecimento.</p></details></template></template></section></template>
